 $('#practice-restart').onclick=()=>{if(!trip)return;trip.node=trip.origin.node;trip.history=trip.history.filter(h=>h.leg!==trip.leg);trip.meters=trip.history.reduce((n,h)=>n+h.meters,0);trip.status='driving';trip.heading=0;trip.legStarted=Date.now();review=false;defaultChoice();message('Trip restarted. The same crossing conditions apply.');instance.setView(network.nodes[trip.node],16);draw();drawRoads();};
 instance.on('moveend zoomend',drawRoads);const observer=new ResizeObserver(()=>instance.invalidateSize());observer.observe($('#practice-map'));cleanup=()=>{document.removeEventListener('keydown',key);observer.disconnect();};
